import re
import csv

# Read molecule.md and extract carcinogenic molecules
with open('doc/molecule.md', 'r') as f:
    content = f.read()

carcinogenic_molecules = set()
current_mol = None

lines = content.split('\n')
for line in lines:
    mol_match = re.search(r'(TR\d+)', line)
    if mol_match:
        current_mol = mol_match.group(1)

    if 'carcinogenic' in line.lower():
        if 'non-carcinogenic' not in line.lower():
            if 'inconclusive' not in line.lower():
                if current_mol:
                    carcinogenic_molecules.add(current_mol)

carcinogenic_molecules = sorted(list(carcinogenic_molecules))
print('Carcinogenic molecules:', carcinogenic_molecules)
print('Count:', len(carcinogenic_molecules))

# Read atom.csv and find 4th atom element for each carcinogenic molecule
atoms_by_mol = {}
with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        mol_id = row['molecule_id']
        atom_id = row['atom_id']
        element = row['element']
        if mol_id not in atoms_by_mol:
            atoms_by_mol[mol_id] = []
        atoms_by_mol[mol_id].append((atom_id, element))

# Get 4th atom element for each carcinogenic molecule
results = []
for mol in carcinogenic_molecules:
    if mol in atoms_by_mol and len(atoms_by_mol[mol]) >= 4:
        fourth_atom = atoms_by_mol[mol][3]  # 4th atom (0-indexed = 3)
        results.append([mol, fourth_atom[1]])

print('\n4th atom elements for carcinogenic molecules:')
for r in results:
    print(r)
